```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString)
        : Buffer.from(response.SecretBinary, 'base64').toString();

      // Cache the result
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error('Secret retrieval failed');
    }
  }

  // For local development only - load from env with warnings
  getSecretSync(envVar) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Sync secret access not allowed in production');
    }
    console.warn(`⚠️  Loading ${envVar} from environment - use secrets manager in production`);
    return process.env[envVar];
  }
}

module.exports = new SecretsManager();
```

