### Long-term: Implement Secrets Manager

Here's a secure configuration module using AWS Secrets Manager (similar patterns for HashiCorp Vault, GCP Secret Manager, Azure Key Vault):

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.TTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName) && Date.now() < this.cacheExpiry.get(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        secret = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      // Cache the secret
      this.cache.set(secretName, secret);
      this.cacheExpiry.set(secretName, Date.now() + this.TTL);

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error('Failed to retrieve secret');
    }
  }

  // Clear sensitive data from memory when done
  clearCache() {
    this.cache.clear();
    this.cacheExpiry.clear();
  }
}

module.exports = new SecretsManager();
```

