```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = JSON.parse(buff.toString('ascii'));
      }

      // Cache the result
      this.cache.set(secretName, { value: secretValue, timestamp: Date.now() });
      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw error;
    }
  }
}

// Usage in app initialization
const secretsManager = new SecretsManager();

async function initializeApp() {
  const dbSecrets = await secretsManager.getSecret('myapp/production/database');
  const apiKeys = await secretsManager.getSecret('myapp/production/api-keys');

  // Use secrets
  const dbUrl = `postgres://${dbSecrets.username}:${dbSecrets.password}@${dbSecrets.host}:${dbSecrets.port}/${dbSecrets.database}`;

  return { dbUrl, apiKeys };
}
```

