#### Option 1: Use a Secrets Manager (Recommended for Production)

```javascript
// Using AWS Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function getSecrets() {
  const client = new SecretsManagerClient({ region: 'us-east-1' });

  try {
    const response = await client.send(
      new GetSecretValueCommand({ SecretId: 'app/production/secrets' })
    );
    return JSON.parse(response.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secrets:', error.message);
    process.exit(1);
  }
}

// Initialize app with secrets
async function startApp() {
  const secrets = await getSecrets();
  process.env.DATABASE_URL = secrets.DATABASE_URL;
  // ... start server
}
```

#### Option 2: Use HashiCorp Vault

```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN
});

async function getSecrets() {
  const { data } = await vault.read('secret/data/app/production');
  return data.data;
}
```

